[TFMPageType('UnplannedItemRegistration', "Unplanned Item Registration")]
class TFMPageUnplannedItemRegistrationConfiguration extends TFMPageConfiguration
{
    str                 useRegistrationCollector;
    boolean             includeInputDataRowInSubmitRequest;
    boolean             automaticAcceptAfterLastScan;
    boolean	            automaticAcceptOnOpen;
    boolean	            enabled;
    TFMPageID           navigateTo;
    TFMPageID           navigateToOnSuccess;
    boolean             close;
    boolean             refreshOnSuccess;
    boolean	            clearAfterPost;
    boolean	            postAllRegistrationsEnabled;
    TFMDocumentTypeId   getRegistrationConfiguration;
    TFMDocumentTypeId	submit;

    //offline configurations
    boolean			    viewRegistrationsEnabled;
    TFMPageID			viewRegistrationsNavigateTo;
    TFMPageTitleString	viewRegistrationsTitle;
    boolean	            offlineServiceEnabled;
    TFMWorkflowName     workFlowId;
    TFMListId           listId;

}

Method.Source:
[TFMPageConfigurationAttributeAttribute('','')]
public str parmType(str _type = type)
{
    type = _type;
    return type;
}

[TFMPageConfigurationAttributeAttribute('auto','','',false,false)]
public str parmUseRegistrationCollector(str _useRegistrationCollector = useRegistrationCollector)
{
    useRegistrationCollector = _useRegistrationCollector;  
    return useRegistrationCollector;
}

[TFMPageConfigurationAttributeAttribute(false,'')]
public boolean parmIncludeInputDataRowInSubmitRequest(boolean _includeInputDataRowInSubmitRequest = includeInputDataRowInSubmitRequest)
{
    includeInputDataRowInSubmitRequest = _includeInputDataRowInSubmitRequest;
    return includeInputDataRowInSubmitRequest;
}

[TFMPageConfigurationAttributeAttribute(true,'header','',true)]
public boolean parmAutomaticAcceptAfterLastScan(boolean _automaticAcceptAfterLastScan = automaticAcceptAfterLastScan)
{
    automaticAcceptAfterLastScan = _automaticAcceptAfterLastScan;
    return automaticAcceptAfterLastScan;
}

[TFMPageConfigurationAttributeAttribute(true,'header','',true)]
public boolean parmAutomaticAcceptOnOpen(boolean _automaticAcceptOnOpen = automaticAcceptOnOpen)
{
    automaticAcceptOnOpen = _automaticAcceptOnOpen;
    return automaticAcceptOnOpen;
}

[TFMPageConfigurationAttributeAttribute(true,'header','',true)]
public boolean parmClearAfterPost(boolean _clearAfterPost = clearAfterPost)
{
    clearAfterPost =_clearAfterPost;
    return clearAfterPost;
}

[TFMPageConfigurationAttributeAttribute(false,'onSuccessfulPost')]
public boolean parmClose(boolean _close = close)
{
    close = _close;
    return close;
}

[TFMPageConfigurationAttributeAttribute(true,'onSuccessfulPost')]
public boolean parmRefreshOnSuccess(boolean _refreshOnSuccess = refreshOnSuccess)
{
    refreshOnSuccess = _refreshOnSuccess;
    return refreshOnSuccess;
}

[TFMPageConfigurationAttributeAttribute('','onSuccessfulPost','navigateTo')]
public TFMPageID parmNavigateToOnSuccess(TFMPageID _navigateToOnSuccess = navigateToOnSuccess)
{
    navigateToOnSuccess = _navigateToOnSuccess;
    return navigateToOnSuccess;
}

[TFMPageConfigurationAttributeAttribute('','requests/', 'getRegistrationConfiguration')]
public TFMDocumentTypeId parmGetRegistrationConfiguration(TFMDocumentTypeId _getRegistrationConfiguration = getRegistrationConfiguration)
{
    getRegistrationConfiguration = _getRegistrationConfiguration;
    return getRegistrationConfiguration;
}

[TFMPageConfigurationAttributeAttribute('','requests/', 'submit')]
public TFMDocumentTypeId parmSubmit(TFMDocumentTypeId _submit = submit)
{
    submit = _submit;
    return submit;
}

[TFMPageConfigurationAttributeAttribute(false,'offlineRegistrationService','enabled', true)]
public boolean parmOfflineServicesEnabled(boolean _offlineServiceEnabled = offlineServiceEnabled)
{
    offlineServiceEnabled = _offlineServiceEnabled;
    return offlineServiceEnabled;
}

[TFMPageConfigurationAttributeAttribute(false,'postAllRegistrations','enabled'),TFMPageAction(TFMPageMenuItemTypes::OfflinePageMenuItem)]
public boolean parmPostAllRegistrationsEnabled(boolean _postAllRegistrationsEnabled = postAllRegistrationsEnabled)
{
    postAllRegistrationsEnabled = _postAllRegistrationsEnabled;
    return postAllRegistrationsEnabled;
}

[TFMPageConfigurationAttributeAttribute('Standard','offlineRegistrationService','workflowId', true)]
public TFMWorkflowName parmWorkflowId(TFMWorkflowName _workFlowId = workFlowId)
{
    workFlowId = _workFlowId;
    return workFlowId;
}

[TFMPageConfigurationAttributeAttribute(classStr(TFMListPendingAdhocRegistrationsList),'offlineRegistrationService/displayLineConfiguration','listId')]
public TFMListId parmOfflineListId(TFMListId _listId = listId)
{
    listId = _listId;
    return listId;
}

[TFMPageConfigurationAttributeAttribute(staticMethodStr(TFMConstants, ViewPendingRegistrations),'offlineRegistrationService/viewRegistrations','navigateTo',true), TFMPageAction(TFMPageMenuItemTypes::OfflinePageMenuItem)]
public TFMPageID parmViewRegistrationsNavigateTo(TFMPageID _viewRegistrationsNavigateTo = viewRegistrationsNavigateTo)
{
    viewRegistrationsNavigateTo = _viewRegistrationsNavigateTo;
    return this.parmOfflineServicesEnabled() ? viewRegistrationsNavigateTo : '';
}

[TFMPageConfigurationAttributeAttribute('ViewRegistrations','offlineRegistrationService/viewRegistrations','title',true), TFMPageAction(TFMPageMenuItemTypes::OfflinePageMenuItem)]
public TFMPageTitleString parmViewRegistrationsTitle(TFMPageTitleString _viewRegistrationsTitle = viewRegistrationsTitle)
{
    viewRegistrationsTitle = _viewRegistrationsTitle;
    return viewRegistrationsTitle;
}
